    status?: string;
    currentPeriodStart?: Date | null;
    currentPeriodEnd?: Date | null;
    cancelAtPeriodEnd?: boolean;
  }
): Promise<boolean> {
  const updateData: Record<string, unknown> = {};

  if (updates.plan !== undefined) {
    updateData.plan = updates.plan;
  }
  if (updates.status !== undefined) {
    updateData.status = updates.status;
  }
  if (updates.currentPeriodStart !== undefined) {
    updateData.currentPeriodStart = updates.currentPeriodStart?.toISOString() ?? null;
  }
  if (updates.currentPeriodEnd !== undefined) {
    updateData.currentPeriodEnd = updates.currentPeriodEnd?.toISOString() ?? null;
  }
  if (updates.cancelAtPeriodEnd !== undefined) {
    updateData.cancelAtPeriodEnd = updates.cancelAtPeriodEnd;
  }
  updateData.updatedAt = new Date().toISOString();

  const { error } = await supabase
    .from('subscriptions')
    .update(updateData)
    .eq('stripeSubscriptionId', stripeSubscriptionId);

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error updating subscription by Stripe ID');
    return false;
  }
  return true;
}


// ============ Emotional History Functions ============

export async function recordEmotionalHistory(data: {
  userId: number;
  externalUserId?: string | null;
  emotion: string;
  valence: number;
  arousal: number;
  escalationRisk?: 'low' | 'medium' | 'high';
  context?: string | null;
  conversationId?: string | null;
}): Promise<number | null> {
  const { data: insertedData, error } = await supabase
    .from('emotional_history')
    .insert({
      user_id: data.userId,
      external_user_id: data.externalUserId ?? null,
      emotion: data.emotion,
      valence: data.valence,
      arousal: data.arousal,
      escalation_risk: data.escalationRisk ?? 'low',
      context: data.context ?? null,
      conversation_id: data.conversationId ?? null,
    })
    .select('id')
    .single();

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error recording emotional history');
    return null;
  }
  return insertedData?.id ?? null;
}

export async function getEmotionalHistoryByUser(userId: number, externalUserId?: string, limit: number = 50): Promise<EmotionalHistory[]> {
  let query = supabase
    .from('emotional_history')
    .select('*')
    .eq('user_id', userId);

  if (externalUserId) {
    query = query.eq('external_user_id', externalUserId);
  }

  const { data, error } = await query
    .order('created_at', { ascending: false })
    .limit(limit);

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error getting emotional history');
    return [];
  }
  return data || [];
}

// ============ Emotional Pattern Functions ============

export async function saveEmotionalPattern(data: {
  userId: number;
  externalUserId?: string | null;
  patternType: 'recurring_frustration' | 'escalation_prone' | 'positive_engagement' | 'time_sensitive' | 'topic_triggered';
  description: string;
  triggers?: string | null;
  frequency?: number;
  recommendedApproach?: string | null;
}): Promise<boolean> {
  const { error } = await supabase
    .from('emotional_patterns')
    .insert({
      user_id: data.userId,
      external_user_id: data.externalUserId ?? null,
      pattern_type: data.patternType,
      description: data.description,
      triggers: data.triggers ?? null,
      frequency: data.frequency ?? 1,
      recommended_approach: data.recommendedApproach ?? null,
    });

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error saving emotional pattern');
    return false;
  }
  return true;
}

export async function getEmotionalPatternsByUser(userId: number, externalUserId?: string): Promise<EmotionalPattern[]> {
  let query = supabase
    .from('emotional_patterns')
    .select('*')
    .eq('user_id', userId);

  if (externalUserId) {
    query = query.eq('external_user_id', externalUserId);
  }

  const { data, error } = await query.order('updated_at', { ascending: false });

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error getting emotional patterns');
    return [];
  }
  return data || [];
}

export async function findExistingPattern(userId: number, externalUserId: string, patternType: string): Promise<EmotionalPattern | null> {
  const { data, error } = await supabase
    .from('emotional_patterns')
    .select('*')
    .eq('user_id', userId)
    .eq('external_user_id', externalUserId)
    .eq('pattern_type', patternType)
    .single();

  if (error) {
    if (error.code !== 'PGRST116') { // Not found is not an error
      dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error finding emotional pattern');
    }
    return null;
  }
  return data;
}

export async function updateEmotionalPattern(
  patternId: number,
  updates: {
    description?: string;
    triggers?: string | null;
    recommendedApproach?: string | null;
    frequency?: number;
  }
): Promise<boolean> {
  const updateData: Record<string, unknown> = {
    updated_at: new Date().toISOString(),
  };

  if (updates.description !== undefined) {
    updateData.description = updates.description;
  }
  if (updates.triggers !== undefined) {
    updateData.triggers = updates.triggers;
  }
  if (updates.recommendedApproach !== undefined) {
    updateData.recommended_approach = updates.recommendedApproach;
  }
  if (updates.frequency !== undefined) {
    updateData.frequency = updates.frequency;
  }

  const { error } = await supabase
    .from('emotional_patterns')
    .update(updateData)
    .eq('id', patternId);

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error updating emotional pattern');
    return false;
  }
  return true;
}

