/**
 * Supabase Database Layer for Gravito
 * 
 * This module provides database operations using Supabase's JavaScript client.
 * It mirrors the functionality in db.ts but uses Supabase PostgreSQL instead of MySQL.
 * 
 * To use Supabase as the primary database:
 * 1. Create tables in Supabase Dashboard (SQL Editor)
 * 2. Import functions from this file instead of db.ts
 * 3. Update routers.ts to use supabase-db functions
 */

import { supabase } from './supabase';
import { createHash, randomBytes } from 'crypto';
import { dbLog } from './_core/logger';
import { ENV } from './_core/env';

// ============ Types ============

export interface User {
  id: number;
  open_id: string;
  name: string | null;
  email: string | null;
  login_method: string | null;
  password_hash: string | null;
  role: 'admin' | 'user';
  last_signed_in: string | null;
  created_at: string;
  updated_at: string;
}

export interface ApiKey {
  id: number;
  user_id: number;
  key_hash: string;
  key_prefix: string;
  name: string;
  is_active: boolean;
  last_used_at: string | null;
  created_at: string;
}

export interface Subscription {
  id: number;
  user_id: number;
  plan: string;
  stripe_customer_id: string | null;
  stripe_subscription_id: string | null;
  status: string;
  current_period_start: string | null;
  current_period_end: string | null;
  cancel_at_period_end: boolean;
  created_at: string;
  updated_at: string;
}

export interface ApiUsage {
  id: number;
  user_id: number;
  api_key_id: number | null;
  endpoint: string;
  call_count: number;
  date: string;
  created_at: string;
}

export interface BillingHistory {
  id: number;
  user_id: number;
  stripe_invoice_id: string | null;
  stripe_payment_intent_id: string | null;
  amount: number;
  currency: string;
  status: string;
  description: string | null;
  created_at: string;
}

export interface RateLimit {
  id: number;
  key: string;
  count: number;
  window_start: string;
  expires_at: string;
}

export interface EmotionalHistory {
  id: number;
  user_id: number;
  external_user_id: string | null;
  emotion: string;
  valence: number;
  arousal: number;
  escalation_risk: 'low' | 'medium' | 'high';
  context: string | null;
  conversation_id: string | null;
  created_at: string;
}

export interface EmotionalPattern {
  id: number;
  user_id: number;
  external_user_id: string | null;
  pattern_type: 'recurring_frustration' | 'escalation_prone' | 'positive_engagement' | 'time_sensitive' | 'topic_triggered';
  description: string;
  triggers: string | null;
  frequency: number;
  last_occurrence: string;
  recommended_approach: string | null;
  created_at: string;
  updated_at: string;
}

export interface Lead {
  id: number;
  email: string;
  company_name: string | null;
  company_size: string | null;
  industry: string | null;
  source_page: string | null;
  utm_source: string | null;
  utm_medium: string | null;
  utm_campaign: string | null;
  escalation_risk: number | null;
  churn_probability: number | null;
  value_at_risk: number | null;
  lead_score: number;
  lead_tier: 'cold' | 'warm' | 'hot' | 'qualified';
  status: string;
  notes: string | null;
  created_at: string;
  updated_at: string;
}

// ============ User Functions ============

export async function upsertUser(userData: {
  openId: string;
  name?: string | null;
  email?: string | null;
  loginMethod?: string | null;
  passwordHash?: string | null;
  role?: 'admin' | 'user';
  lastSignedIn?: Date;
}): Promise<User | null> {
  // Build the upsert payload from ONLY the fields the caller actually provided.
  // PostgREST upsert (resolution=merge-duplicates) updates exactly the columns
  // present in the payload on conflict and leaves omitted columns UNCHANGED, so
  // partial updates (e.g. the per-request `last_signed_in` touch from
  // authenticateRequest, which passes only openId + lastSignedIn) must NOT carry
  // name/email/role — otherwise an existing user's profile and, critically, an
  // admin's `role` would be clobbered to defaults on every login/request.
  //
  // `role` is only written when explicitly provided, else self-healed to 'admin'
  // for the owner openId; otherwise it is omitted so the existing value is
  // preserved on conflict (and falls back to the column default 'user' on a true
  // insert). Mirrors the role-preservation + owner self-heal in server/db.ts.
  const payload: Record<string, unknown> = {
    open_id: userData.openId,
    last_signed_in: userData.lastSignedIn?.toISOString() ?? new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  if (userData.name !== undefined) payload.name = userData.name ?? null;
  if (userData.email !== undefined) payload.email = userData.email ?? null;
  if (userData.loginMethod !== undefined) payload.login_method = userData.loginMethod ?? null;
  if (userData.passwordHash !== undefined) payload.password_hash = userData.passwordHash ?? null;
  if (userData.role !== undefined) {
    payload.role = userData.role;
  } else if (userData.openId && userData.openId === ENV.ownerOpenId) {
    payload.role = 'admin';
  }

  const { data, error } = await supabase
    .from('users')
    .upsert(payload, {
      onConflict: 'open_id',
    })
    .select()
    .single();

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error upserting user');
    return null;
  }
  return data;
}

export async function getUserByOpenId(openId: string): Promise<User | null> {
  const { data, error } = await supabase
    .from('users')
    .select('*')
    .eq('open_id', openId)
    .single();

  if (error) {
    if (error.code !== 'PGRST116') { // Not found is expected
      dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error getting user by openId');
    }
    return null;
  }
  return data;
}

export async function getUserById(id: number): Promise<User | null> {
  const { data, error } = await supabase
    .from('users')
    .select('*')
    .eq('id', id)
    .single();

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error getting user by id');
    return null;
  }
  return data;
}

export async function getUserByEmail(email: string): Promise<User | null> {
  const { data, error } = await supabase
    .from('users')
    .select('*')
    .eq('email', email)
    .single();

  if (error) {
    if (error.code !== 'PGRST116') {
      dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error getting user by email');
    }
    return null;
  }
  return data;
}

// ============ API Key Functions ============

function hashApiKey(key: string): string {
  return createHash('sha256').update(key).digest('hex');
}

export function generateApiKey(): { key: string; hash: string; prefix: string } {
  const key = `grav_${randomBytes(32).toString('hex')}`;
  const hash = hashApiKey(key);
  // Prod `api_keys.key_prefix` is varchar(12) NOT NULL — a 16-char prefix
  // overflows it (Postgres 22001) and silently fails key creation/regeneration.
  const prefix = key.substring(0, 12);
  return { key, hash, prefix };
}

export async function createApiKey(userId: number, name?: string): Promise<{ key: string; prefix: string } | null> {
  const { key, hash, prefix } = generateApiKey();

  const { error } = await supabase
    .from('api_keys')
    .insert({
      user_id: userId,
      key_hash: hash,
      key_prefix: prefix,
      name: name || 'Default Key',
      is_active: true,
    });

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error creating API key');
    return null;
  }
  return { key, prefix };
}

/** The six columns the listing query below projects — never the key hash. */
export type ApiKeySummaryRow = Pick<
  ApiKey,
  'id' | 'key_prefix' | 'name' | 'is_active' | 'last_used_at' | 'created_at'
>;

export async function getApiKeysByUserId(userId: number): Promise<ApiKeySummaryRow[]> {
  const { data, error } = await supabase
    .from('api_keys')
    .select('id, key_prefix, name, is_active, last_used_at, created_at')
    .eq('user_id', userId);

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error getting API keys');
    return [];
  }
  return data || [];
}

export async function validateApiKey(key: string): Promise<ApiKey | null> {
  const hash = hashApiKey(key);

  const { data, error } = await supabase
    .from('api_keys')
    .select('*')
    .eq('key_hash', hash)
    .eq('is_active', true)
    .single();

  if (error) {
    return null;
  }

  // Update last used
  await supabase
    .from('api_keys')
    .update({ last_used_at: new Date().toISOString() })
    .eq('id', data.id);

  return data;
}

export async function deleteApiKey(userId: number, keyId: number): Promise<boolean> {
  const { error } = await supabase
    .from('api_keys')
    .delete()
    .eq('id', keyId)
    .eq('user_id', userId);

  return !error;
}

export async function regenerateApiKey(userId: number, keyId: number): Promise<{ key: string; prefix: string } | null> {
  const { key, hash, prefix } = generateApiKey();

  const { error } = await supabase
    .from('api_keys')
    .update({ key_hash: hash, key_prefix: prefix })
    .eq('id', keyId)
    .eq('user_id', userId);

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error regenerating API key');
    return null;
  }
  return { key, prefix };
}

// ============ Subscription Functions ============

export async function getSubscriptionByUserId(userId: number): Promise<Subscription | null> {
  const { data, error } = await supabase
    .from('subscriptions')
    .select('*')
    .eq('userId', userId)
    .single();

  if (error) {
    if (error.code !== 'PGRST116') {
      dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error getting subscription');
    }
    return null;
  }
  return data;
}

export async function createOrUpdateSubscription(subData: {
  userId: number;
  plan: string;
  stripeCustomerId?: string | null;
  stripeSubscriptionId?: string | null;
  status?: string;
  currentPeriodStart?: Date | null;
  currentPeriodEnd?: Date | null;
  cancelAtPeriodEnd?: boolean;
}): Promise<boolean> {
  const { error } = await supabase
    .from('subscriptions')
    .upsert({
      userId: subData.userId,
      plan: subData.plan,
      stripeCustomerId: subData.stripeCustomerId ?? null,
      stripeSubscriptionId: subData.stripeSubscriptionId ?? null,
      status: subData.status ?? 'active',
      currentPeriodStart: subData.currentPeriodStart?.toISOString() ?? null,
      currentPeriodEnd: subData.currentPeriodEnd?.toISOString() ?? null,
      cancelAtPeriodEnd: subData.cancelAtPeriodEnd ?? false,
      updatedAt: new Date().toISOString(),
    }, {
      onConflict: 'userId',
    });

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error creating/updating subscription');
    return false;
  }
  return true;
}

// ============ Usage Functions ============

export async function recordApiUsage(userId: number, apiKeyId: number | null, endpoint: string): Promise<void> {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const todayStr = today.toISOString().split('T')[0];

  // Try to find existing record for today
  const { data: existing } = await supabase
    .from('api_usage')
    .select('id, callCount')
    .eq('userId', userId)
    .eq('endpoint', endpoint)
    .eq('date', todayStr)
    .single();

  if (existing) {
    // Increment existing record
    await supabase
      .from('api_usage')
      .update({ callCount: existing.callCount + 1 })
      .eq('id', existing.id);
  } else {
    // Create new record
    await supabase
      .from('api_usage')
      .insert({
        userId: userId,
        apiKeyId: apiKeyId,
        endpoint,
        callCount: 1,
        date: todayStr,
      });
  }
}

export async function getUsageByUserId(userId: number, days: number = 30): Promise<ApiUsage[]> {
  const startDate = new Date();
  startDate.setDate(startDate.getDate() - days);

  const { data, error } = await supabase
    .from('api_usage')
    .select('*')
    .eq('userId', userId)
    .gte('date', startDate.toISOString().split('T')[0])
    .order('date', { ascending: false });

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error getting usage');
    return [];
  }
  return data || [];
}

export async function getTotalUsageThisMonth(userId: number): Promise<number> {
  const startOfMonth = new Date();
  startOfMonth.setDate(1);
  startOfMonth.setHours(0, 0, 0, 0);

  const { data, error } = await supabase
    .from('api_usage')
    .select('callCount')
    .eq('userId', userId)
    .gte('date', startOfMonth.toISOString().split('T')[0]);

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error getting total usage');
    return 0;
  }

  return data?.reduce((sum, row) => sum + (row.callCount || 0), 0) || 0;
}

// ============ Billing Functions ============

export async function addBillingRecord(billingData: {
  userId: number;
  stripeInvoiceId?: string | null;
  stripePaymentIntentId?: string | null;
  amount: number;
  currency?: string;
  status: string;
  description?: string | null;
}): Promise<boolean> {
  const { error } = await supabase
    .from('billing_history')
    .insert({
      userId: billingData.userId,
      stripeInvoiceId: billingData.stripeInvoiceId ?? null,
      // NOTE: prod `billing_history` has NO payment-intent column (verified against
      // drizzle/schema.ts + drizzle/migrations/0000_clean_whistler.sql — only the
      // `fix_orders` table carries `stripePaymentIntentId`). Inserting it would 400
      // the whole row, so the caller-supplied stripePaymentIntentId is intentionally
      // NOT written here. The param is kept on the signature for caller compatibility.
      amount: billingData.amount,
      currency: billingData.currency ?? 'usd',
      status: billingData.status,
      description: billingData.description ?? null,
    });

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error adding billing record');
    return false;
  }
  return true;
}

export async function getBillingHistory(userId: number, limit: number = 10): Promise<BillingHistory[]> {
  const { data, error } = await supabase
    .from('billing_history')
    .select('*')
    .eq('userId', userId)
    .order('createdAt', { ascending: false })
    .limit(limit);

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error getting billing history');
    return [];
  }
  return data || [];
}

// ============ Rate Limiting Functions ============

export async function checkRateLimit(userId: number, plan: string): Promise<{
  allowed: boolean;
  remaining: number;
  resetAt: Date;
}> {
  const planLimits: Record<string, { calls: number; rate: number }> = {
    free: { calls: 2000, rate: 10 },
    builder: { calls: 25000, rate: 60 },
    startup: { calls: 150000, rate: 300 },
    scale: { calls: 500000, rate: 1000 },
    business: { calls: 2000000, rate: 5000 },
    enterprise: { calls: Infinity, rate: 10000 },
    enterprise_plus: { calls: Infinity, rate: 50000 },
  };

  const limits = planLimits[plan] || planLimits.free;
  const key = `rate:${userId}`;
  const now = new Date();
  const _windowStart = new Date(now.getTime() - 60000); // 1 minute window (reserved for windowed rate-limit)

  // Get or create rate limit record
  const { data: existing } = await supabase
    .from('rate_limits')
    .select('*')
    .eq('key', key)
    .gte('expires_at', now.toISOString())
    .single();

  if (existing) {
    const allowed = existing.count < limits.rate;
    if (allowed) {
      await supabase
        .from('rate_limits')
        .update({ count: existing.count + 1 })
        .eq('id', existing.id);
    }
    return {
      allowed,
      remaining: Math.max(0, limits.rate - existing.count - 1),
      resetAt: new Date(existing.expires_at),
    };
  }

  // Create new rate limit window
  const expiresAt = new Date(now.getTime() + 60000);
  await supabase
    .from('rate_limits')
    .insert({
      key,
      count: 1,
      window_start: now.toISOString(),
      expires_at: expiresAt.toISOString(),
    });

  return {
    allowed: true,
    remaining: limits.rate - 1,
    resetAt: expiresAt,
  };
}

// ============ Leads Functions ============

function calculateLeadScore(data: {
  escalationRisk?: number;
  churnProbability?: number;
  valueAtRisk?: number;
}): { score: number; tier: 'cold' | 'warm' | 'hot' | 'qualified' } {
  let score = 0;

  if (data.escalationRisk) {
    score += Math.round(data.escalationRisk * 0.4);
  }
  if (data.churnProbability) {
    score += Math.round(data.churnProbability * 0.3);
  }
  if (data.valueAtRisk) {
    const valueScore = Math.min(data.valueAtRisk / 10000, 1) * 30;
    score += Math.round(valueScore);
  }

  let tier: 'cold' | 'warm' | 'hot' | 'qualified';
  if (score >= 70) tier = 'qualified';
  else if (score >= 50) tier = 'hot';
  else if (score >= 30) tier = 'warm';
  else tier = 'cold';

  return { score, tier };
}

export async function createLead(leadData: {
  email: string;
  companyName?: string | null;
  companySize?: string | null;
  industry?: string | null;
  sourcePage?: string | null;
  utmSource?: string | null;
  utmMedium?: string | null;
  utmCampaign?: string | null;
  escalationRisk?: number | null;
  churnProbability?: number | null;
  valueAtRisk?: number | null;
}): Promise<Lead | null> {
  const { score, tier } = calculateLeadScore({
    escalationRisk: leadData.escalationRisk ?? undefined,
    churnProbability: leadData.churnProbability ?? undefined,
    valueAtRisk: leadData.valueAtRisk ?? undefined,
  });

  const { data, error } = await supabase
    .from('leads')
